// Local design simulations only. Settings and personas never leave this browser.
window.AssistantPreview = (() => {
  const key='sary-assistant-preview-v1';
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tones=[['friendly','ودود'],['professional','رسمي'],['casual','عفوي'],['empathetic','متعاطف'],['persuasive','مقنع']];
  const avatars=[['support','دعم فني'],['sales','مبيعات'],['reception','استقبال'],['manager','مدير'],['tech','تقني'],['marketing','تسويق'],['consultant','استشاري'],['creative','إبداعي'],['analyst','محلل'],['hr','موارد بشرية'],['finance','مالي'],['default','عام']];
  const blank=()=>({name:'',role:'',department:'',personalityPrompt:'',tone:'friendly',avatarEmoji:'reception',isDefault:false,isActive:true,triggerKeywords:[],shiftStart:'',shiftEnd:''});
  const templates=()=>[
    {...blank(),id:1,name:'سارة',role:'موظفة استقبال',department:'الاستقبال',isDefault:true,triggerKeywords:['مرحبا','السلام','هلا'],personalityPrompt:'رحّبي بالعميل وافهمي طلبه ووجّهيه إلى الاختصاص المناسب.'},
    {...blank(),id:2,name:'فهد',role:'مسؤول مبيعات',department:'المبيعات',avatarEmoji:'sales',tone:'persuasive',triggerKeywords:['سعر','شراء','عرض'],personalityPrompt:'افهم احتياج العميل واقترح الحل المناسب من المعرفة المعتمدة، دون ضغط أو وعود غير مؤكدة.'},
    {...blank(),id:3,name:'نورة',role:'أخصائية دعم',department:'الدعم',avatarEmoji:'support',tone:'empathetic',triggerKeywords:['مشكلة','ارجاع','شكوى'],personalityPrompt:'ساعدي العميل بهدوء، واستعيني بالفريق عند غياب المعلومة أو الصلاحية.'}
  ];
  const initial=()=>({agents:templates(),settings:{autoReplyEnabled:true,tone:'friendly',language:'ar',responseDelay:2,maxResponseLength:200,workingHoursEnabled:false,workingHoursStart:'09:00',workingHoursEnd:'18:00',workingDays:['0','1','2','3','4'],welcomeMessage:'أهلًا بك! كيف أقدر أساعدك اليوم؟',outOfHoursMessage:'وصلتنا رسالتك. نعود إليك خلال أوقات العمل.',groupMode:'disabled',groupKeywords:'سعر، توفر',groupRedirectMessage:'يسعدنا مساعدتك في الخاص.',customInstructions:'',discountEnabled:false,maxPercent:10,expireHours:24,marginEnabled:false,minPercent:0,takeoverTimeoutMinutes:'15',takeoverResumeMessage:'مرحبًا! عدت لخدمتك.',takeoverCommandsEnabled:true},history:[]});
  let data;try{data=JSON.parse(localStorage.getItem(key)||'null');}catch{}if(!data?.agents||!data?.settings)data=initial();
  let current='',section='basics',draft={...data.settings},agent=null,agentTab='identity',keyword='',errors={},search='';
  const routes=['virtual-team','bot-settings','human-takeover','language-settings','ai-hub'];
  const handles=p=>routes.includes(p.route.replace('/merchant/',''));
  const save=()=>{try{localStorage.setItem(key,JSON.stringify(data));}catch{toast('تعذر الحفظ الدائم. التغييرات متاحة في الجلسة الحالية.');}};
  const btn=(label,action,extra='',primary=false)=>`<button type="button" class="button ${primary?'primary':''}" data-as-action="${action}" ${extra}>${e(label)}</button>`;
  const link=(label,route)=>`<a class="button" href="#/page/merchant/${route}">${e(label)}</a>`;
  const badge=(label,gray=false)=>`<span class="status ${gray?'gray':''}">${e(label)}</span>`;
  const avatar=(a)=>`<span class="as-avatar" aria-hidden="true">${e((a.name||avatars.find(v=>v[0]===a.avatarEmoji)?.[1]||'س').slice(0,1))}</span>`;
  const field=(name,label,{type='text',options,help='',min,max,maxlength=100,required=false,scope='settings'}={})=>{
    const values=scope==='agent'?agent:draft,value=values[name]??'',id=`as-${name}`;
    const attrs=`id="${id}" name="${name}" data-as-field="${scope}" ${required?'required':''} ${errors[name]?`aria-invalid="true" aria-describedby="${id}-error"`:''}`;
    const input=type==='checkbox'?`<input ${attrs} type="checkbox" ${value?'checked':''}>`:options?`<select class="control" ${attrs}>${options.map(([v,l])=>`<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(l)}</option>`).join('')}</select>`:type==='textarea'?`<textarea ${attrs} rows="4" maxlength="${maxlength}">${e(value)}</textarea>`:`<input ${attrs} type="${type}" value="${e(value)}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} maxlength="${maxlength}" ${['time','number'].includes(type)?'dir="ltr"':''}>`;
    return `<div class="field ${type==='checkbox'?'as-check':''}">${type==='checkbox'?`<label for="${id}">${input}<span>${e(label)}</span></label>`:`<label for="${id}">${e(label)} ${required?'*':''}</label>${input}`}${help?`<small class="hint">${e(help)}</small>`:''}${errors[name]?`<p class="as-error" id="${id}-error" role="alert">${e(errors[name])}</p>`:''}</div>`;
  };
  let routingMessage='', routingTime='12:00';
  function routingResult(){
    const available=data.agents.filter(a=>a.isActive&&(!a.shiftStart&&!a.shiftEnd||a.shiftStart&&a.shiftEnd&&(a.shiftStart<a.shiftEnd?routingTime>=a.shiftStart&&routingTime<a.shiftEnd:routingTime>=a.shiftStart||routingTime<a.shiftEnd)));
    const matched=routingMessage.trim()?available.find(a=>a.triggerKeywords.some(k=>k.trim()&&routingMessage.toLowerCase().includes(k.toLowerCase()))):null;
    const chosen=matched||available.find(a=>a.isDefault)||available[0];
    return chosen?chosen.name+' · '+(matched?'تطابق كلمة التحويل':chosen.isDefault?'الشخصية الافتراضية المتاحة':'الأولوية الأولى المتاحة'):'لا توجد شخصية متاحة؛ يتولى المساعد الأساسي الرد وفق إعداداته.';
  }
  function team(){
    const agents=data.agents.filter(a=>`${a.name} ${a.role} ${a.department}`.includes(search));
    return `<div class="as-summary"><div><b>${data.agents.length} / 10</b><span>شخصيات الفريق</span></div><div><b>${data.agents.filter(a=>a.isActive).length}</b><span>شخصيات نشطة</span></div><div><b>${e(data.agents.find(a=>a.isDefault)?.name||'غير محددة')}</b><span>الشخصية الافتراضية</span></div></div><div class="toolbar"><div class="field"><label for="as-team-search">ابحث بالاسم أو الدور</label><input id="as-team-search" value="${e(search)}"></div>${link('إعدادات المساعد','bot-settings')}${link('اختبر التحويل','test-sari')}</div><div class="as-team-grid">${agents.map(a=>`<article class="panel as-persona"><div class="as-persona-actions"><span>الأولوية ${data.agents.findIndex(x=>x.id===a.id)+1}</span>${btn("رفع","move-up",`data-id="${a.id}" aria-label="رفع أولوية ${e(a.name)}" ${data.agents[0].id===a.id?"disabled":""}`)}${btn("خفض","move-down",`data-id="${a.id}" aria-label="خفض أولوية ${e(a.name)}" ${data.agents.at(-1).id===a.id?"disabled":""}`)}</div><div class="as-persona-head">${avatar(a)}<div><h2>${e(a.name)}</h2><p>${e(a.role)}</p></div>${a.isDefault?badge('افتراضية'):''}</div><div class="as-pills">${badge(a.isActive?'نشطة':'متوقفة',!a.isActive)}${badge(tones.find(t=>t[0]===a.tone)?.[1],true)}${a.department?badge(a.department,true):''}</div><p class="as-prompt">${e(a.personalityPrompt)}</p><small>${a.shiftStart?`${e(a.shiftStart)} – ${e(a.shiftEnd)}`:'دون جدول خاص بالشخصية'}</small><div class="as-pills">${a.triggerKeywords.map(k=>`<span class="as-keyword">${e(k)}</span>`).join('')}</div><div class="as-persona-actions">${btn('اختبر الرد','preview-persona',`data-id="${a.id}" aria-label="اختبار رد ${e(a.name)}"`)}${btn('تعديل الشخصية','edit',`data-id="${a.id}"`)}${btn('حذف','delete',`data-id="${a.id}" aria-label="حذف ${e(a.name)}"`)}</div></article>`).join('')}</div>${!agents.length?`<section class="panel panel-pad"><h2>${search?'لا توجد نتائج':'ابدأ بفريقك الافتراضي'}</h2><p>فريق جاهز للاستقبال والمبيعات والدعم، يمكنك تعديل تفاصيله.</p>${!data.agents.length?btn('استخدام فريق جاهز','seed','',true):btn('مسح البحث','clear-search')}</section>`:''}<section class="panel panel-pad"><h2>من سيستقبل هذا الطلب؟</h2><p>محاكاة الكلمات والأولوية والدوام بتوقيت الرياض. لا تُرسل رسالة.</p><div class="as-two"><label for="as-routing-message">رسالة العميل<input id="as-routing-message" maxlength="500" value="${e(routingMessage)}"></label><label for="as-routing-time">الوقت · الرياض<input id="as-routing-time" type="time" value="${e(routingTime)}"></label></div><p id="as-routing-result" role="status">${e(routingResult())}</p>${btn('اختبر الرد حسب التوجيه','preview-routing')}</section><section class="as-note"><h2>شخصية واضحة، وتحويل مفهوم</h2><p>ابدأ بالدور والأسلوب. أضف الكلمات والدوام عند الحاجة. يظل عقل ساري مصدر المعلومات المعتمدة، والتجربة هي وسيلتك للتحقق من الرد الفعلي.</p>${link('نتائج عقل ساري','sari-brain')}${link('قواعد التدخل البشري','human-takeover')}</section>`;
  }
  function openAgent(id){agent=structuredClone(data.agents.find(a=>a.id===Number(id))||blank());agentTab='identity';keyword='';errors={};editDialog();}
  function editDialog(){
    openDialog(agent.id?'تعديل الشخصية':'شخصية جديدة',`<form data-as-form="agent" class="as-editor" novalidate><p class="hint">الأساسيات أولًا. إعدادات التحويل والدوام في قسم مستقل.</p><nav class="as-tabs" aria-label="إعداد الشخصية">${[['identity','الشخصية والأسلوب'],['routing','التحويل والدوام']].map(([v,l])=>btn(l,'agent-tab',`data-value="${v}" aria-pressed="${agentTab===v}"`)).join('')}</nav><div class="as-editor-body">${agentTab==='identity'?`<div class="field-grid">${field('name','الاسم',{scope:'agent',required:true})}${field('role','الدور',{scope:'agent',required:true})}</div>${field('department','القسم · اختياري',{scope:'agent'})}<details class="as-avatar-picker"><summary>الصورة الرمزية · ${e(avatars.find(v=>v[0]===agent.avatarEmoji)?.[1]||'عام')}</summary><div>${avatars.map(([v,l])=>`<button type="button" data-as-action="avatar" data-value="${v}" aria-pressed="${agent.avatarEmoji===v}"><span class="as-avatar">${e(l[0])}</span>${l}</button>`).join('')}</div></details><fieldset><legend>أسلوب الحديث</legend><div class="as-pills">${tones.map(([v,l])=>btn(l,'tone',`data-value="${v}" aria-pressed="${agent.tone===v}"`)).join('')}</div></fieldset>${field('personalityPrompt','مهمة الشخصية وحدودها',{scope:'agent',type:'textarea',maxlength:2000,required:true,help:'وضّح ما تساعد فيه العميل ومتى تستعين بالفريق. الأسعار والسياسات المتغيرة مكانها ملفات المعرفة.'})}<small class="hint">حتى 2000 حرف</small>`:`<div class="field"><label for="as-keyword">كلمات التحويل</label><p class="hint">كلمة أو عبارة لكل اختصاص. لا تُضاف الكلمة مرتين.</p><div class="as-keyword-input"><input id="as-keyword" maxlength="100" value="${e(keyword)}">${btn('إضافة','keyword')}</div><div class="as-pills">${agent.triggerKeywords.map((k,i)=>btn(`${k} ×`,'remove-keyword',`data-index="${i}" aria-label="حذف الكلمة ${e(k)}"`)).join('')}</div>${errors.triggerKeywords?`<p class="as-error" role="alert">${errors.triggerKeywords}</p>`:''}</div><fieldset><legend>ساعات الشخصية</legend><p class="hint">اترك الوقتين فارغين لإلغاء الجدول الخاص. يبقى جدول المساعد العام مؤثرًا في الرد.</p><div class="field-grid">${field('shiftStart','من',{scope:'agent',type:'time'})}${field('shiftEnd','إلى',{scope:'agent',type:'time'})}</div>${btn('إلغاء جدول الشخصية','clear-hours')}</fieldset>${field('isDefault','الشخصية الافتراضية',{scope:'agent',type:'checkbox',help:'اختيارها يستبدل الشخصية الافتراضية السابقة.'})}${agent.id?field('isActive','الشخصية نشطة',{scope:'agent',type:'checkbox',help:'أوقفها مؤقتًا مع الاحتفاظ بإعداداتها.'}):''}`}</div><div class="as-savebar"><small>* حقل مطلوب</small>${btn('إلغاء','close')}<button class="button primary" type="submit">حفظ الشخصية</button></div></form>`);
  }
  const sections=[['basics','الرد والأسلوب'],['schedule','أوقات العمل'],['groups','المجموعات والتعليمات'],['sales','صلاحيات البيع'],['preview','المعاينة']];
  const languageOptions=[['ar','العربية'],['en','English'],['fr','Français'],['tr','Türkçe'],['es','Español'],['it','Italiano'],['both','عربي وإنجليزي']];
  function settings(){
    let body='';
    if(section==='basics')body=`${field('autoReplyEnabled','تفعيل الرد التلقائي',{type:'checkbox'})}<div class="field-grid">${field('tone','أسلوب الرد',{options:tones.slice(0,3)})}${field('language','لغة ردود المساعد',{options:languageOptions})}${field('responseDelay','مهلة الرد بالثواني',{type:'number',min:1,max:10,required:true})}${field('maxResponseLength','الحد الأقصى لطول الرد',{type:'number',min:50,max:500,required:true})}</div><details class="as-template-picker"><summary>قوالب جاهزة · 9 خيارات</summary><p class="hint">اختيار القالب يغيّر مسودة الترحيب والأسلوب والمهلة. راجعها قبل الحفظ.</p><div class="as-pills">${['رسمي','ودود','عصري','مطعم','أزياء','إلكترونيات','تجميل','عقارات','خدمات'].map((name,i)=>btn(name,'bot-template',`data-index="${i}"`)).join('')}</div></details>`;
    if(section==='schedule')body=`${field('workingHoursEnabled','تحديد أوقات العمل',{type:'checkbox'})}<fieldset ${draft.workingHoursEnabled||errors.workingHoursStart||errors.workingHoursEnd?'':'disabled'}><legend>جدول الرد</legend><div class="as-pills">${['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'].map((day,i)=>btn(day,'day',`data-value="${i}" aria-pressed="${draft.workingDays.includes(String(i))}"`)).join('')}</div>${draft.workingDays.length?'':'<p class="hint">لم تحدد أي يوم. لن تتاح الردود المجدولة حتى تختار يومًا أو توقف تحديد أوقات العمل.</p>'}<div class="field-grid">${field('workingHoursStart','بداية الدوام',{type:'time'})}${field('workingHoursEnd','نهاية الدوام',{type:'time'})}</div></fieldset>${field('welcomeMessage','رسالة الترحيب',{type:'textarea',maxlength:1000})}${field('outOfHoursMessage','الرد خارج الدوام',{type:'textarea',maxlength:1000})}`;
    if(section==='groups')body=`${field('groupMode','التعامل مع المجموعات',{options:[['disabled','إيقاف كامل'],['mention_only','عند الإشارة للمساعد'],['keyword_only','كلمات مفتاحية'],['private_redirect','التحويل للخاص']]})}${draft.groupMode==='keyword_only'?field('groupKeywords','الكلمات المفتاحية',{help:'افصل بين الكلمات بفاصلة.'}):''}${draft.groupMode==='private_redirect'?field('groupRedirectMessage','رسالة التحويل للخاص',{type:'textarea',maxlength:500}):''}${field('customInstructions','تعليمات خاصة للمساعد',{type:'textarea',maxlength:2000,help:'قواعد التعامل وحدود الصلاحيات؛ لا تستبدل المصادر الموثقة.'})}`;
    if(section==='sales')body=policies();
    if(section==='preview')body=`<div class="as-chat"><h3>معاينة رسائل المسودة</h3><span class="status gray">عرض نصي · لا يختبر النموذج الفعلي</span>${draft.autoReplyEnabled?`<p class="as-reply">${e(draft.welcomeMessage)}</p>${draft.workingHoursEnabled?`<p class="hint">خارج أوقات العمل</p><p class="as-reply">${e(draft.outOfHoursMessage)}</p>`:'<p class="hint">جدول العمل متوقف في المسودة؛ رسالة خارج الدوام لا تنطبق.</p>'}`:'<p>الرد التلقائي متوقف في المسودة.</p>'}<p class="hint">هذه الرسائل لا تقيس احتراف المبيعات أو اكتمال المعرفة.</p></div><h3>اختبار الإعدادات المحفوظة</h3><p class="hint">يستخدم إعدادات المعاينة المحفوظة محليًا، ولا يشمل تعديلات المسودة. النتيجة مثال ثابت وليست إجابة من النموذج.</p><div class="as-pills">${btn('اختبر الرد','preview-store')}${btn('معاينة إرسال اختبار','test-message')}</div>`;
    return `<div class="as-settings-layout"><aside class="as-settings-nav panel"><p class="eyebrow">اضبط المساعد</p>${sections.map(([id,l])=>btn(l,'section',`data-value="${id}" aria-pressed="${section===id}"`)).join('')}<hr>${link('الشخصيات','virtual-team')}${link('التدخل البشري','human-takeover')}${link('ملفات المعرفة','sari-brain')}</aside><section class="panel panel-pad"><header class="as-section-title"><h2>${sections.find(s=>s[0]===section)[1]}</h2><span class="status gray">مسودة محلية</span></header><form data-as-form="settings" class="form-stack">${body}${section!=='sales'?`<div class="as-savebar"><p class="hint">يحفظ إعدادات الرد. سياسات البيع تُحفظ كلٌ على حدة.</p><button type="submit" class="button primary">حفظ إعدادات الرد</button></div>`:''}</form></section></div>`;
  }
  function policies(){return `<p class="hint">الأرقام توضيحية. حفظ كل سياسة يتطلب مراجعة مستقلة؛ لا يغيّر أسعار متجر حقيقي.</p>${['discount','margin'].map(kind=>`<section class="as-policy"><h3>${kind==='discount'?'صلاحية منح الخصم':'الحد الأدنى لهامش الربح'}</h3>${field(kind==='discount'?'discountEnabled':'marginEnabled','تفعيل السياسة',{type:'checkbox'})}<div class="field-grid">${kind==='discount'?field('maxPercent','أقصى خصم %',{type:'number',min:1,max:50,required:true})+field('expireHours','صلاحية العرض بالساعات',{type:'number',min:1,max:168,required:true}):field('minPercent','أقل هامش ربح %',{type:'number',min:0,max:100,required:true})}</div><p class="hint">${kind==='discount'?'الخصم لا يتجاوز الحد المسموح، وتبقى قيود الربح والصلاحيات سارية.':'يُراجع بعد احتساب تكلفة المنتجات والضريبة والشحن والتكاليف الأخرى.'}</p><label class="check-label"><input id="as-review-${kind}" type="checkbox">راجعت أثر هذه السياسة على البيع</label>${btn('اعتماد السياسة','policy',`data-kind="${kind}"`)}<details><summary>سجل التغييرات</summary><ul>${data.history.filter(h=>h.kind===kind).map(h=>`<li>${e(h.text)}</li>`).join('')||'<li>لم تُحفظ تغييرات في هذه المعاينة.</li>'}</ul></details></section>`).join('')}`;}
  function takeover(){return `<div class="as-settings-layout"><section class="panel panel-pad"><h2>متى يعود ساري للرد؟</h2><p>يصمت أثناء تدخّل الفريق، ثم يعود بعد مدة التوقف المحددة.</p><form data-as-form="takeover" class="form-stack">${field('takeoverTimeoutMinutes','الانتظار بعد آخر تدخل',{options:[['5','5 دقائق'],['15','15 دقيقة'],['30','30 دقيقة'],['60','60 دقيقة']]})}${field('takeoverResumeMessage','رسالة العودة',{type:'textarea',maxlength:500})}${field('takeoverCommandsEnabled','تفعيل عبارات الإيقاف والاستئناف',{type:'checkbox'})}${draft.takeoverCommandsEnabled?'<div class="as-note"><p>إيقاف: سأتولى المحادثة / I’ll take over</p><p>استئناف: يسعدنا خدمتكم / Glad to help</p></div>':''}<button class="button primary" type="submit">حفظ قواعد التدخل</button></form></section><aside class="panel panel-pad"><h2>تحت إدارة الفريق</h2><p class="hint">مثال لحالة المحادثات عند تدخل الموظف.</p><div class="list-row"><div><strong>نورة · متابعة الطلب</strong><p>إيقاف مؤقت · 12 دقيقة متبقية</p></div></div><div class="list-row"><div><strong>خالد · شكوى شحن</strong><p>إيقاف يدوي · حتى أمر الاستئناف</p></div></div>${link('فتح المحادثات','conversations')}</aside></div>`;}
  function language(){return `<section class="panel panel-pad as-language"><h2>لغة ردود المساعد</h2><p>اختيار لغة المحادثة لا يغيّر عملة المتجر.</p><form data-as-form="language" class="form-stack">${field('language','لغة المساعد',{options:languageOptions.slice(0,6)})}<div class="as-note"><h3>معاينة الترحيب</h3><p>${e(({ar:'مرحبًا! كيف يمكنني مساعدتك؟',en:'Hello! How can I help you?',fr:'Bonjour ! Comment puis-je vous aider ?',tr:'Merhaba! Size nasıl yardımcı olabilirim?',es:'¡Hola! ¿Cómo puedo ayudarte?',it:'Ciao! Come posso aiutarti?'})[draft.language]||'مرحبًا / Hello')}</p></div><button type="submit" class="button primary">حفظ لغة المساعد</button></form></section>`;}
  function hub(){const items=[['sari-brain','عقل ساري','النتائج، الملفات، فجوات المعرفة واحتراف المبيعات'],['virtual-team','شخصيات الفريق','الأدوار، الأسلوب، الكلمات والدوام'],['bot-settings','إعدادات المساعد','الرد، المجموعات، التعليمات وصلاحيات البيع'],['human-takeover','التدخل البشري','الإيقاف والاستئناف والمحادثات تحت إدارة الفريق'],['language-settings','لغة المحادثة','لغة المساعد ومعاينة الرد'],['test-sari','جرّب ساري','اختبار الردود قبل الاعتماد'],['sari-playground','مختبر ساري','تجارب المحادثة'],['quick-responses','الردود السريعة والكلمات','قواعد الكلمات والردود'],['ai-suggestions','الاقتراحات','فرص تحسين الرد'],['voice-messages','الرسائل الصوتية','الاستخدام والأداء'],['scheduled-messages','الرسائل المجدولة','المستلم والوقت والحالة'],['whatsapp-auto-notifications','تنبيهات واتساب','قوالب إشعارات المواعيد'],['sari-analytics','تحليلات ساري','مراجعة أداء المحادثات']];return `<div class="as-hub-grid">${items.map(([r,t,d])=>`<a class="panel as-hub-card" href="#/page/merchant/${r}"><span class="as-hub-dot"></span><h2>${t}</h2><p>${d}</p><span>افتح القسم ←</span></a>`).join('')}</div>`;}
  function renderPage(p){if(current!==p.route){current=p.route;draft=structuredClone(data.settings);section='basics';search='';errors={};}return ({'virtual-team':team,'bot-settings':settings,'human-takeover':takeover,'language-settings':language,'ai-hub':hub})[p.route.replace('/merchant/','')]();}
  function primary(p){if(p.route.endsWith('/virtual-team')){if(data.agents.length>=10)return toast('الحد الأقصى 10 شخصيات.');openAgent();}else if(p.route.endsWith('/ai-hub'))location.hash='#/page/merchant/test-sari';else document.querySelector('[data-as-form]')?.requestSubmit();}
  function validateAgent(){errors={};for(const name of ['name','role','personalityPrompt'])if(!agent[name].trim())errors[name]='أكمل هذا الحقل.';if(Boolean(agent.shiftStart)!==Boolean(agent.shiftEnd)||agent.shiftStart&&agent.shiftStart===agent.shiftEnd)errors.shiftStart='أدخل وقتين مختلفين، أو أفرغهما معًا.';if(JSON.stringify(agent.triggerKeywords).length>2000)errors.triggerKeywords='قائمة الكلمات أطول من الحد المسموح.';return !Object.keys(errors).length;}
  function remember(event){const input=event.target;if(!input.dataset.asField)return;const target=input.dataset.asField==='agent'?agent:draft;target[input.name]=input.type==='checkbox'?input.checked:input.type==='number'?input.value===''?'':Number(input.value):input.value;document.querySelectorAll('[id^="as-review-"]').forEach(n=>n.checked=false);}
  document.addEventListener('input',event=>{remember(event);if(event.target.id==='as-routing-message'||event.target.id==='as-routing-time'){if(event.target.id==='as-routing-message')routingMessage=event.target.value;else routingTime=event.target.value;document.getElementById('as-routing-result').textContent=routingResult();}if(event.target.id==='as-keyword')keyword=event.target.value;if(event.target.id==='as-team-search'){search=event.target.value;const start=event.target.selectionStart;window.render();const input=document.getElementById('as-team-search');input.focus();input.setSelectionRange(start,start);}});
  document.addEventListener('change',event=>{remember(event);if(['groupMode','workingHoursEnabled','takeoverCommandsEnabled','language'].includes(event.target.name)&&event.target.dataset.asField==='settings')window.render();});
  document.addEventListener('keydown',event=>{if(event.target.id==='as-keyword'&&event.key==='Enter'){event.preventDefault();document.querySelector('[data-as-action="keyword"]').click();}});

  let replyPreview=null;
  function openReplyPreview(mode,id){
    const validTime=/^([01]\d|2[0-3]):[0-5]\d$/.test(routingTime);
    let selected=mode==='manual'?data.agents.find(a=>a.id===Number(id)):null;
    if(mode==='automatic'){
      if(!validTime||!routingMessage.trim())return toast('أدخل رسالة ووقتًا صحيحًا بتوقيت الرياض.');
      const available=data.agents.filter(a=>a.isActive&&(!a.shiftStart&&!a.shiftEnd||a.shiftStart&&a.shiftEnd&&a.shiftStart!==a.shiftEnd&&(a.shiftStart<a.shiftEnd?routingTime>=a.shiftStart&&routingTime<a.shiftEnd:routingTime>=a.shiftStart||routingTime<a.shiftEnd)));
      selected=available.find(a=>a.triggerKeywords.some(k=>k.trim()&&routingMessage.toLowerCase().includes(k.toLowerCase())))||available.find(a=>a.isDefault)||available[0];
      if(!selected)return toast('لا توجد شخصية نشطة ضمن هذا الوقت.');
    }
    replyPreview={mode,selected};
    openDialog('اختبار رد الشخصية والإعدادات',`<div class="form-stack"><p>محاكاة تصميم محلية؛ لا تستدعي نموذجًا ولا تراسل العملاء. تستخدم بيانات المعاينة المحفوظة فقط.</p>${selected?`<h3>${e(selected.name)} · ${e(selected.role)}</h3><p class="hint">${mode==='manual'?'اختيار يدوي يتجاوز التوجيه والدوام في المعاينة فقط':'اختيار تلقائي بتوقيت الرياض: '+e(routingTime)}${!selected.isActive?' · شخصية متوقفة؛ لم يتم تفعيلها':''}</p>`:''}<div class="field"><label for="as-preview-question">سؤال العميل</label><textarea id="as-preview-question" maxlength="2000" rows="4">${e(mode==='automatic'?routingMessage:'')}</textarea></div><p class="hint">كل سؤال مستقل. لا تحفظ هذه التجربة بعد إغلاقها.</p><div class="as-pills">${btn('اختبر الرد','preview-send','',true)}${btn('محاكاة تعذر الرد','preview-failure')}</div><div id="as-preview-result" role="status" aria-live="polite"></div></div>`);
  }

  document.addEventListener('click',event=>{
    const node=event.target.closest('[data-as-action]');if(!node)return;const a=node.dataset.asAction;
    if(a==='preview-persona')openReplyPreview('manual',node.dataset.id);
    if(a==='preview-routing')openReplyPreview('automatic');
    if(a==='preview-store')openReplyPreview('store');
    if(a==='preview-send'||a==='preview-failure'){
      const question=document.getElementById('as-preview-question').value.trim();
      if(!question)return toast('اكتب سؤال العميل أولًا.');
      const result=document.getElementById('as-preview-result');
      result.innerHTML=a==='preview-failure'?'<p role="alert">تعذر الرد في هذا المثال. بقي سؤالك؛ أعد الاختبار للمحاولة.</p>':`<h3>مثال ثابت لعرض النتيجة · لم يستدع نموذجًا</h3><p>السؤال الذي جرى اختباره: ${e(question)}</p><p>مثال توضيحي: أهلًا، ${e(replyPreview.selected?.name||'مساعد المتجر')} معك. ما التفاصيل التي تحتاج مساعدتنا فيها؟</p><small>لا يثبت جودة الرد أو اكتمال المعرفة أو نجاح المبيعات.</small>`;
    }
    if(a==='move-up'||a==='move-down'){const from=data.agents.findIndex(x=>x.id===Number(node.dataset.id)),to=from+(a==='move-up'?-1:1);if(from>=0&&to>=0&&to<data.agents.length){[data.agents[from],data.agents[to]]=[data.agents[to],data.agents[from]];save();window.render();}}
    if(a==='edit')openAgent(node.dataset.id);
    if(a==='agent-tab'){agentTab=node.dataset.value;editDialog();}
    if(a==='avatar'||a==='tone'){agent[a==='avatar'?'avatarEmoji':'tone']=node.dataset.value;editDialog();if(a==='avatar')document.querySelector('.as-avatar-picker').open=true;}
    if(a==='keyword'){const word=keyword.trim();if(word&&!agent.triggerKeywords.includes(word))agent.triggerKeywords.push(word);keyword='';editDialog();document.getElementById('as-keyword').focus();}
    if(a==='remove-keyword'){agent.triggerKeywords.splice(Number(node.dataset.index),1);editDialog();}
    if(a==='clear-hours'){agent.shiftStart='';agent.shiftEnd='';errors.shiftStart=undefined;editDialog();}
    if(a==='delete')openDialog('حذف الشخصية',`<p>سيُحذف ${e(data.agents.find(x=>x.id===Number(node.dataset.id))?.name)} وإعداداته من المعاينة.</p><div class="dialog-foot">${btn('إلغاء','close')}${btn('تأكيد الحذف','confirm-delete',`data-id="${node.dataset.id}"`)}</div>`);
    if(a==='confirm-delete'){data.agents=data.agents.filter(x=>x.id!==Number(node.dataset.id));save();document.getElementById('dialog').close();window.render();}
    if(a==='seed'){if(!data.agents.length){data.agents=templates();save();window.render();}}
    if(a==='clear-search'){search='';window.render();}
    if(a==='close')document.getElementById('dialog').close();
    if(a==='section'){section=node.dataset.value;window.render();}
    if(a==='day'){const value=node.dataset.value;draft.workingDays=draft.workingDays.includes(value)?draft.workingDays.filter(x=>x!==value):[...draft.workingDays,value];window.render();}
    if(a==='bot-template'){const i=Number(node.dataset.index);draft.tone=['professional','friendly','casual','friendly','friendly','professional','friendly','professional','friendly'][i];draft.responseDelay=i===0||i===7?3:i===2?1:2;draft.welcomeMessage=['مرحبًا بكم. كيف يمكننا مساعدتكم؟','أهلًا! كيف أقدر أساعدك؟','هلا بك! وش تحتاج اليوم؟','أهلًا بك في مطعمنا. كيف نساعدك بطلبك؟','أهلًا! نساعدك في اختيار ما يناسبك.','مرحبًا. ما الجهاز أو المواصفات التي تبحث عنها؟','أهلًا بك. كيف يمكننا مساعدتك؟','مرحبًا بكم. ما العقار الذي تبحثون عنه؟','أهلًا بك. ما الخدمة التي تحتاجها؟'][i];draft.outOfHoursMessage='شكرًا لرسالتك. سنعود إليك خلال أوقات العمل.';window.render();toast('تم تطبيق القالب على المسودة.');}
    if(a==='test-message')openDialog('رسالة الاختبار',`<p>في التطبيق الفعلي تُرسل رسالة الترحيب المحفوظة إلى رقم المتجر المسجل. هذه معاينة محلية؛ لم تُرسل رسالة. لا تشمل تعديلات المسودة.</p><div class="as-note">${e(data.settings.welcomeMessage)}</div>`);
    if(a==='policy'){
      const kind=node.dataset.kind,names=kind==='discount'?['discountEnabled','maxPercent','expireHours']:['marginEnabled','minPercent'];
      if(!names.every(name=>document.getElementById(`as-${name}`)?.reportValidity()))return;
      if(!document.getElementById(`as-review-${kind}`).checked)return toast('راجع أثر السياسة وحدد مربع المراجعة قبل الاعتماد.');
      const before=names.map(n=>data.settings[n]).join(' / ');for(const n of names)data.settings[n]=draft[n];data.history.unshift({kind,text:`قبل: ${before} ← بعد: ${names.map(n=>draft[n]).join(' / ')} · حفظ محلي`});save();window.render();toast('تم حفظ السياسة محليًا.');
    }
  });
  document.addEventListener('submit',event=>{
    const type=event.target.dataset.asForm;if(!type)return;event.preventDefault();
    if(type==='agent'){
      if(keyword.trim()&&!agent.triggerKeywords.includes(keyword.trim()))agent.triggerKeywords.push(keyword.trim());
      if(!validateAgent()){agentTab=errors.name||errors.role||errors.personalityPrompt?'identity':'routing';editDialog();document.querySelector('[aria-invalid="true"]')?.focus();return;}
      if(!agent.id&&data.agents.length>=10)return toast('الحد الأقصى 10 شخصيات.');
      const next={...agent,name:agent.name.trim(),role:agent.role.trim(),personalityPrompt:agent.personalityPrompt.trim(),id:agent.id||Date.now()};
      if(next.isDefault)data.agents=data.agents.map(a=>({...a,isDefault:false}));
      const index=data.agents.findIndex(a=>a.id===next.id);if(index<0)data.agents.push(next);else data.agents[index]=next;
      save();document.getElementById('dialog').close();window.render();toast('تم حفظ الشخصية في هذه المعاينة.');return;
    }
    if(!event.target.reportValidity())return;
    if(type==='settings'&&section==='sales')return toast('اعتمد كل سياسة من زرها بعد المراجعة.');
    let names=type==='takeover'?['takeoverTimeoutMinutes','takeoverResumeMessage','takeoverCommandsEnabled']:type==='language'?['language']:Object.keys(draft).filter(n=>!['discountEnabled','maxPercent','expireHours','marginEnabled','minPercent'].includes(n));
    if(type==='settings'){
      errors={};
      for(const name of ['workingHoursStart','workingHoursEnd'])if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(draft[name]))errors[name]='أدخل وقتًا صحيحًا بين 00:00 و23:59.';
      if(draft.workingHoursEnabled&&!errors.workingHoursStart&&!errors.workingHoursEnd&&draft.workingHoursStart===draft.workingHoursEnd)errors.workingHoursEnd='اختر وقت نهاية يختلف عن البداية. للعمل طوال اليوم، أوقف تحديد أوقات العمل.';
      if(Object.keys(errors).length){section='schedule';window.render();document.querySelector('[aria-invalid="true"]')?.focus();return;}
    }
    for(const name of names)data.settings[name]=draft[name];save();toast('تم حفظ التغييرات محليًا.');
  });
  return {handles,render:renderPage,primary,reset(){data=initial();draft=structuredClone(data.settings);current='';save();}};
})();
